				if (output_map) {
					write(`${output_dir}/${file}.css.map`, JSON.stringify(compiled.css.map, null, '\t'));
				}
			}

			if (compiled.warnings.length > 0) {
				write(`${output_dir}/${file}.warnings.json`, JSON.stringify(compiled.warnings, null, '\t'));
			}
		}
	}
